-- parameters: []
WITH _normal AS (SELECT DATE_TRUNC('year', balance_month) AS "balance_month", SUM(balance) AS "account_balance_first" FROM (SELECT account_id, region, balance_month, balance FROM marts.balances WHERE NOT region LIKE 'test%') AS "balances" GROUP BY DATE_TRUNC('year', balance_month)), _base AS (SELECT DATE_TRUNC('month', balance_month) AS "balance_month", SUM(balance) AS "account_balance_first" FROM (SELECT account_id, region, balance_month, balance FROM marts.balances WHERE NOT region LIKE 'test%') AS "balances" GROUP BY DATE_TRUNC('month', balance_month)), _ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('year', "balance_month") ORDER BY "balance_month" ASC) AS "_rank_account_balance_first" FROM _base), _rollup AS (SELECT DATE_TRUNC('year', "balance_month") AS "balance_month", MAX(CASE WHEN "_rank_account_balance_first" = 1 THEN "account_balance_first" END) AS "account_balance_first" FROM _ranked GROUP BY DATE_TRUNC('year', "balance_month")) SELECT n."balance_month" AS "balance_month", r."account_balance_first" AS "account_balance_first" FROM _normal n JOIN _rollup r ON n."balance_month" IS NOT DISTINCT FROM r."balance_month" LIMIT 1000
